struct Cancel{unsigned calls=0,at=0;}; bool Stop(void* p) noexcept {auto& x=*static_cast<Cancel*>(p);return ++x.calls==x.at;}
dt::DateExecutionControlV3 Control(Cancel& c,uint64_t budget=~uint64_t{0}){return {budget,Stop,&c};}
struct PinProbe{unsigned calls=0,at=0;std::weak_ptr<const dt::DateValidatedProfileHandleV3> profile;long baseline=0;long observed=0;};
bool StopWithPin(void* p) noexcept {auto& x=*static_cast<PinProbe*>(p);++x.calls;x.observed=x.profile.use_count();return x.calls==x.at;}
dt::DateExecutionControlV3 PinControl(PinProbe& p,uint64_t budget=~uint64_t{0}){return {budget,StopWithPin,&p};}
struct ScrubObservation{std::array<unsigned,static_cast<std::size_t>(dt::DateScrubClassV3::count)> calls{};std::array<p::u64,static_cast<std::size_t>(dt::DateScrubClassV3::count)> maximum_extent{};bool all_zero=true;unsigned total()const{return std::accumulate(calls.begin(),calls.end(),0u);}};
void ObserveScrub(void* raw,dt::DateScrubClassV3 scrub_class,const p::byte* bytes,p::u64 extent) noexcept{auto& observation=*static_cast<ScrubObservation*>(raw);const auto index=static_cast<std::size_t>(scrub_class);++observation.calls[index];observation.maximum_extent[index]=std::max(observation.maximum_extent[index],extent);for(p::u64 i=0;i<extent;++i)observation.all_zero=observation.all_zero&&bytes[i]==0;}
dt::DateExecutionControlV3 Observed(ScrubObservation& observation){dt::DateExecutionControlV3 control{};control.observe_scrubbed=ObserveScrub;control.scrub_observer_context=&observation;return control;}
bool Seen(const ScrubObservation& observation,dt::DateScrubClassV3 scrub_class){return observation.calls[static_cast<std::size_t>(scrub_class)]!=0;}
std::vector<p::byte> Hex(std::string_view s){auto n=[](char c){return unsigned(c<='9'?c-'0':10+(c|32)-'a');};std::vector<p::byte> r(s.size()/2);for(size_t i=0;i<r.size();++i)r[i]=p::byte((n(s[2*i])<<4)|n(s[2*i+1]));return r;}
