template<class Invoke>void ExactGuardMatrix(std::string_view label,std::span<const p::byte> expected,Invoke invoke){const std::size_t required=expected.size();auto fresh=[&]{return std::vector<p::byte>(3+required+5,0xa5);};auto success=fresh();auto result=invoke(success.data()+3,required,dt::DateExecutionControlV3{});Check(result.ok()&&result.bytes_written==required,label);Check(std::equal(expected.begin(),expected.end(),success.begin()+3),"exact bounded bytes");for(std::size_t i=0;i<3;++i)Check(success[i]==0xa5,"three prefix guards");for(std::size_t i=3+required;i<success.size();++i)Check(success[i]==0xa5,"five suffix guards");auto short_buffer=fresh();const auto short_before=short_buffer;Check(!invoke(short_buffer.data()+3,required-1,dt::DateExecutionControlV3{}).ok()&&short_buffer==short_before,"short capacity preserves guards");auto cancelled=fresh();const auto cancelled_before=cancelled;Cancel cancel{0,1};Check(!invoke(cancelled.data()+3,required,Control(cancel)).ok()&&cancelled==cancelled_before,"cancellation preserves guards");auto resource=fresh();const auto resource_before=resource;dt::DateExecutionControlV3 limited{};limited.maximum_allocation_bytes=required-1;Check(!invoke(resource.data()+3,required,limited).ok()&&resource==resource_before,"resource refusal preserves guards");}
