void HeapFailureAndRetry() {
  auto profile = Profile();
  dt::DateOwnedValueV3 value{profile, dt::DateValueStateV3::value, 0};
  const auto* text_identity = Identity(dt::CanonicalTypeId::character);
  const auto text_descriptor = Descriptor(dt::CanonicalTypeId::character);
  const dt::DateTextOperandV3 text_operand{
      text_identity, &text_descriptor, dt::DateTextCarrierKindV3::utf8_bytes,
      dt::DateValueStateV3::value, "1970-01-01", 10};
  const auto val_oracle = dt::EncodeDateSbdvalComposedV3(value, true);
  const auto pv_oracle = dt::EncodeDateSbdpvComposedV3(value, true);
  Check(text_identity != nullptr && val_oracle.ok() && pv_oracle.ok(),
        "no-allocation oracles");

  std::array<p::byte, 4> component{};
  std::array<char, 21> rendered{};
  std::array<p::byte, 32> hash{};
  std::array<p::byte, 104> key{};
  constexpr std::array<std::int32_t, 2> days{{0, 1}};
  constexpr std::array<p::byte, 1> bitmap{{0}};
  const dt::DateNullableI64FactV3 year{
      dt::DateI64CarrierKindV3::signed_i64, dt::DateValueStateV3::value, 1970};
  const dt::DateNullableI64FactV3 month{
      dt::DateI64CarrierKindV3::signed_i64, dt::DateValueStateV3::value, 1};
  const dt::DateNullableI64FactV3 day{
      dt::DateI64CarrierKindV3::signed_i64, dt::DateValueStateV3::value, 1};

  allocation_probe::count = true;
  allocation_probe::allocations = 0;
  BeginHeapFailure();
  const bool noalloc_ok =
      dt::ValidateDateProfileHandleV3(*profile).ok() &&
      dt::ValidateDateValueViewV3(value.view()).ok() &&
      dt::AdmitDateOperandV3(
          {profile, dt::DateValueStateV3::value,
           dt::DateDayCarrierKindV3::signed_i32, 0}).ok() &&
      dt::ConstructDateFromCivilV3(profile, 1970, 1, 1).ok() &&
      dt::ConstructDateFromCivilV3(profile, year, month, day).ok() &&
      dt::DecomposeDateCivilV3(value.view()).ok() &&
      dt::ParseCanonicalDateV3(profile, "1970-01-01").ok() &&
      dt::ParseCanonicalDateOperandV3(profile, text_operand).ok() &&
      dt::ValidateCanonicalDateV3(value).ok() &&
      dt::TruncateDateDayV3(value).ok() &&
      dt::RoundDateDayV3(value).ok() &&
      dt::AddDateDaysV3(value, 1).ok() &&
      dt::SubtractDateDaysV3(value, 1).ok() &&
      dt::DateSuccessorV3(value).ok() &&
      dt::DatePredecessorV3(value).ok() &&
      dt::DifferenceDateDaysV3(value.view(), value.view()).ok() &&
      dt::DateIsLeapYearV3(value.view()).ok() &&
      dt::DateDaysInMonthV3(value.view()).ok() &&
      dt::DateIsoWeekdayV3(value.view()).ok() &&
      dt::DateDayOfYearV3(value.view()).ok() &&
      dt::DateQuarterV3(value.view()).ok() &&
      dt::DateIsoWeekV3(value.view()).ok() &&
      dt::CompareDateValuesV3(value.view(), value.view()).ok() &&
      dt::EncodeCanonicalDateComponentIntoNoAllocV3(
          value, component.data(), component.size()).ok() &&
      dt::DecodeCanonicalDateComponentNoAllocV3(
          *profile, dt::DateValueStateV3::value, true, component).ok() &&
      dt::RenderCanonicalDateIntoNoAllocV3(
          value, true, rendered.data(), rendered.size()).ok() &&
      dt::HashDateValueIntoNoAllocV3(value, hash.data(), hash.size()).ok() &&
      dt::MakeDateSortKeyIntoNoAllocV3(
          value, dt::DateSortDirectionV3::ascending,
          dt::DateNullModeV3::nulls_first, key.data(), key.size()).ok() &&
      dt::DecodeDateSortKeyNoAllocV3(*profile, key).ok() &&
      dt::DecodeDateSbdvalComposedNoAllocV3(
          *profile, true, val_oracle.bytes).ok() &&
      dt::DecodeDateSbdpvComposedNoAllocV3(
          *profile, true, pv_oracle.bytes).ok() &&
      dt::ValidateDateBatchViewV3({profile.get(), days, bitmap}).ok();
  EndHeapFailure();
  allocation_probe::count = false;
  Check(noalloc_ok && allocation_probe::fail_calls == 0 &&
            allocation_probe::allocations == 0,
        "every promised validation/civil/parse/compare/hash/render/key/decode path allocates no heap");

  BeginHeapFailure();
  const auto owned_component = dt::EncodeCanonicalDateComponentV3(value);
  EndHeapFailure();
  BeginHeapFailure();
  const auto owned_render = dt::RenderCanonicalDateV3(value, true);
  EndHeapFailure();
  BeginHeapFailure();
  const auto owned_hash = dt::HashDateValueV3(value);
  EndHeapFailure();
  BeginHeapFailure();
  const auto owned_key = dt::MakeDateSortKeyV3(
      value, dt::DateSortDirectionV3::ascending,
      dt::DateNullModeV3::nulls_first);
  EndHeapFailure();
  BeginHeapFailure();
  const auto owned_val = dt::EncodeDateSbdvalComposedV3(value, true);
  EndHeapFailure();
  BeginHeapFailure();
  const auto owned_pv = dt::EncodeDateSbdpvComposedV3(value, true);
  EndHeapFailure();
  BeginHeapFailure();
  const auto owned_batch = dt::MaterializeDateBatchV3(profile, days, bitmap);
  EndHeapFailure();
  const auto resource_failure = [](const auto& result) {
    return !result.ok() &&
        result.diagnostic.diagnostic_code == "RESOURCE.BUDGET_EXCEEDED";
  };
  Check(resource_failure(owned_component) && owned_component.bytes.empty() &&
            resource_failure(owned_render) && owned_render.text.empty() &&
            resource_failure(owned_hash) && owned_hash.bytes.empty() &&
            resource_failure(owned_key) && owned_key.bytes.empty() &&
            resource_failure(owned_val) && owned_val.bytes.empty() &&
            resource_failure(owned_pv) && owned_pv.bytes.empty() &&
            resource_failure(owned_batch) && owned_batch.batch.days.empty() &&
            owned_batch.batch.null_bitmap_lsb0.empty(),
        "owning allocation failures map without publication");
  Check(dt::EncodeCanonicalDateComponentV3(value).ok() &&
            dt::RenderCanonicalDateV3(value, true).ok() &&
            dt::HashDateValueV3(value).ok() &&
            dt::MakeDateSortKeyV3(
                value, dt::DateSortDirectionV3::ascending,
                dt::DateNullModeV3::nulls_first).ok() &&
            dt::EncodeDateSbdvalComposedV3(value, true).ok() &&
            dt::EncodeDateSbdpvComposedV3(value, true).ok() &&
            dt::MaterializeDateBatchV3(profile, days, bitmap).ok(),
        "deterministic retry after heap failure");
}
